DD.defineEntity('germ', {   // Germ Shield-X fan: two tiles tall, a fan wearing the blue tub. Walks at you when near, hops every second or so. Stomp it.
  bowl: true,   // a person: Mel's roll knocks them over
  spawn: t => ({ x: t.x + 4, y: t.y + 2, w: 22, h: 30, vx: -0.5, vy: 0, t: (t.tx * 7) % 40, face: -1 }),
  update(e, G) {
    const d = DD.cx(G.pl) - DD.cx(e);
    e.t++;
    if (Math.abs(d) < 140) { e.vx = Math.sign(d) * 0.6; e.face = Math.sign(d) || e.face; }
    if (e.t % 80 === 0 && Math.abs(d) < 200 && e.vy === 0) e.vy = -3.4;
    if (DD.moveX(e, e.vx, false)) e.vx = -e.vx;
    e.vy = Math.min(e.vy + 0.4, 6); if (DD.moveY(e, e.vy, false)) e.vy = 0;
    if (e.y > DD.L.H * 16 + 40) e.dead = true;
  },
  draw(e, ctx, G) {
    const n = e.vy !== 0 ? 'w7_germ2' : (Math.floor(e.t / 9) % 2 ? 'w7_germ2' : 'w7_germ');
    const bob = e.vy === 0 && Math.floor(e.t / 9) % 2 ? 1 : 0;
    if (DD.ready(n)) DD.spr(n, DD.wx(e.x + e.w / 2), DD.wy(e.y + e.h + 3 - bob), e.face > 0);
  },
  stomp(e) { e.dead = true; DD.addGot(2, DD.cx(e), e.y); DD.SFX.stomp(); DD.burst && DD.burst(DD.cx(e), e.y + 8, 6); return true; },
  touch(e) { DD.hurt(DD.cx(e)); },
});
