      for (const [px, py, w] of [[64, 19, 4], [101, 19, 3], [136, 17, 2], [172, 19, 3], [134, 19, 2]]) glow(X(px) + w * 8, Y(py) - 2, 34 + w * 4, 'rgba(120,200,255,0.24)');
      for (const [px, py, w] of [[141, 10, 3], [147, 18, 2], [150, 15, 2], [153, 12, 2], [156, 9, 3], [205, 18, 3], [209, 15, 3]]) glow(X(px) + w * 8, Y(py) + 8, 30 + w * 4, 'rgba(120,200,255,0.20)');
