        ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(sx - 3, sy + 14); ctx.lineTo(sx + 3, sy + 14); ctx.lineTo(sx + 15, Y(21)); ctx.lineTo(sx - 15, Y(21)); ctx.fill();
